function validate(input) {
  const [{ Buses = [], Passengers = [] }] = input;
  const buses = new Set(), times = new Set(), passengers = new Set();
  for (const [id, time, capacity] of Buses) {
    if (id === null || time === null || capacity === null) return 'Every bus needs a bus_id, an arrival_time and a capacity.';
    if (buses.has(id)) return `bus_id ${id} appears twice in Buses.`;
    if (times.has(time)) return `Two buses arrive at time ${time}.`;
    if (capacity < 0) return `Bus ${id} has a negative capacity.`;
    buses.add(id); times.add(time);
  }
  for (const [id, time] of Passengers) {
    if (id === null || time === null) return 'Every passenger needs a passenger_id and an arrival_time.';
    if (passengers.has(id)) return `passenger_id ${id} appears twice in Passengers.`;
    passengers.add(id);
  }
  return null;
}

