function generate(rand, size) {
  const small = size === 'small';
  const busCount = small ? Math.floor(rand() * 6) : 500;
  const passengerCount = small ? Math.floor(rand() * 9) : 2000;
  // Distinct, increasing bus times; bus ids are shuffled so id order differs from arrival order.
  const times = [];
  let t = small ? Math.floor(rand() * 3) : 0;
  for (let i = 0; i < busCount; i++) { t += 1 + Math.floor(rand() * (small ? 3 : 40)); times.push(t); }
  const ids = Array.from({ length: busCount }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const capacities = small ? [0, 1, 1, 2, 3, 5] : [0, 1, 2, 3, 4, 5, 6, 8];
  const Buses = times.map((time, i) => [ids[i], time, capacities[Math.floor(rand() * capacities.length)]]);
  const last = t + (small ? 2 : 50);
  const Passengers = [];
  for (let i = 0; i < passengerCount; i++) Passengers.push([i + 1 + (small ? 10 : 0), Math.floor(rand() * (last + 1))]);
  return [{ Buses, Passengers }];
}
